def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if len(alive_opponents) == 0:
        safe_bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water_days >= 2:
            safe_bid = min(budget, DAILY_SALARY * 0.75)
        return float(max(0.0, safe_bid))

    prev_bids = []
    prev_max = 0.0
    prev_min = None
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 120:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = float(prev.get('bid'))
            prev_bids.append(b)
            if b > prev_max:
                prev_max = b
            if prev_min is None or b < prev_min:
                prev_min = b

    if prev_min is None:
        prev_min = 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0
    low_supply = 1.0 - scarcity

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2

    if no_water_days >= 2:
        urgency += 0.9
    elif no_water_days == 1:
        urgency += 0.35

    pressure = 0.0
    if prev_max >= 120:
        pressure += 0.45
    elif prev_max >= 95:
        pressure += 0.3
    elif prev_max >= 70:
        pressure += 0.15

    pressure += 0.08 * desperate_count
    pressure += 0.04 * rich_count
    pressure += 0.35 * low_supply

    survival_mode = (hp <= 3) or (no_water_days >= 2)
    caution_mode = (hp >= 7 and no_water_days == 0 and supply >= 21)

    if survival_mode:
        bid = max(DAILY_SALARY * 0.95, prev_max + 2.0)
    elif caution_mode and prev_max >= 100:
        bid = DAILY_SALARY * 0.22
    else:
        base = DAILY_SALARY * (0.28 + 0.32 * low_supply + 0.35 * urgency + 0.18 * pressure)
        if prev_bids:
            if low_supply > 0.6 or urgency > 0.45:
                target = prev_max + 1.5
                bid = max(base, target)
            else:
                target = prev_min + 1.0
                bid = max(base, min(target, prev_max * 0.72 if prev_max > 0 else target))
        else:
            bid = base

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.9
    if day >= 8 and (hp <= 4 or no_water_days >= 1):
        bid *= 1.12

    max_affordable = budget
    soft_cap = DAILY_SALARY * 1.55
    if hp >= 7 and no_water_days == 0 and supply >= 22:
        soft_cap = DAILY_SALARY * 0.7
    if survival_mode:
        soft_cap = max(soft_cap, DAILY_SALARY * 1.45)

    bid = min(bid, soft_cap, max_affordable)

    if budget < DAILY_SALARY * 0.6:
        bid = min(bid, budget)
    elif budget > 250 and (low_supply > 0.5 or urgency > 0.4):
        bid = min(max_affordable, bid + 6.0)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    if not alive:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Read only yesterday's immediate behavior
    prev_bids = []
    for o in alive:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many total water units likely available (not exact, but guides aggressiveness)
    # Ensure integer indexing safety by explicit int conversions where needed.
    approx_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0

    # Base aggressiveness by our survival pressure
    critical = (my_hp <= 2) or (my_no_water_days >= 2)

    # Opponent pressure: Cindy died; likely others bid to avoid being outbid.
    # If any opponent bid very high yesterday, assume they were competing for scarce supply.
    very_high_threshold = 0.85 * DAILY_SALARY  # 76.5
    high_bid_threshold = 0.65 * DAILY_SALARY  # 58.5

    # Budget-aware cap so we don't repeat Cindy-like collapse
    # Keep a reserve of one day's salary or a fraction depending on HP.
    reserve_frac = 0.25 if my_hp >= 6 else 0.1
    reserve = DAILY_SALARY * reserve_frac

    max_affordable = max(0.0, my_budget - reserve)
    if max_affordable <= 0.0:
        # Can't safely bid much; bid minimal to try to avoid death
        return float(min(my_budget, DAILY_SALARY * 0.2))

    # Decide bid
    if highest_prev_bid >= very_high_threshold:
        # High pressure: try to beat them slightly, but scale with our HP
        if critical:
            bid = highest_prev_bid + 5.0
        else:
            # If we are healthy, don't overpay; still beat slightly
            bid = max(highest_prev_bid + 2.0, DAILY_SALARY * 0.35)
    elif highest_prev_bid >= high_bid_threshold:
        # Moderate pressure: bid around mid-high to secure
        if critical:
            bid = DAILY_SALARY * 0.75
        else:
            bid = max(DAILY_SALARY * 0.55, highest_prev_bid + 1.5)
    else:
        # Low pressure: conserve budget
        if critical:
            bid = DAILY_SALARY * 0.65
        else:
            bid = DAILY_SALARY * 0.45

    # Supply-aware adjustment: if supply is low, increase bid; if high, slightly decrease.
    if supply <= float(MIN_SUPPLY) + 1e-9:
        bid *= 1.12
    elif supply >= float(MAX_SUPPLY) - 1e-9:
        bid *= 0.92

    # If approx_units is 0, water is extremely scarce; push harder.
    if approx_units <= 0:
        bid *= 1.25

    # Final clamp
    bid = float(bid)
    bid = min(bid, max_affordable)
    bid = min(bid, my_budget)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)

        if day_context['supply'] < WATER_REQ * 1.5:
            return min(my_status['budget'], DAILY_SALARY * 1.1)

        if my_status['hp'] < 4:
            return min(my_status['budget'], max_prev + 5.0)

        return min(my_status['budget'], max(avg_prev + 2.0, DAILY_SALARY * 0.6))

    return min(my_status['budget'], DAILY_SALARY * 0.7)
